select pg_catalog.jsonb_build_object(
 'postgresVersion', pg_catalog.current_setting('server_version'),
 'transactionReadOnly', pg_catalog.current_setting('transaction_read_only'),
 'tables', coalesce((select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
   'name', c.relname, 'rls',c.relrowsecurity, 'forceRls',c.relforcerowsecurity,
   'owner',pg_catalog.pg_get_userbyid(c.relowner),
   'privileges',(select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('role',r.role,'select',pg_catalog.has_table_privilege(r.role,c.oid,'SELECT'),'insert',pg_catalog.has_table_privilege(r.role,c.oid,'INSERT'),'update',pg_catalog.has_table_privilege(r.role,c.oid,'UPDATE'),'delete',pg_catalog.has_table_privilege(r.role,c.oid,'DELETE'),'truncate',pg_catalog.has_table_privilege(r.role,c.oid,'TRUNCATE'),'references',pg_catalog.has_table_privilege(r.role,c.oid,'REFERENCES'),'trigger',pg_catalog.has_table_privilege(r.role,c.oid,'TRIGGER')) order by r.role) from (values('anon'),('authenticated'),('service_role'))r(role)),
   'columns',(select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('name',a.attname,'type',pg_catalog.format_type(a.atttypid,a.atttypmod),'notNull',a.attnotnull,'privileges',(select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('role',r.role,'select',pg_catalog.has_column_privilege(r.role,c.oid,a.attnum,'SELECT'),'insert',pg_catalog.has_column_privilege(r.role,c.oid,a.attnum,'INSERT'),'update',pg_catalog.has_column_privilege(r.role,c.oid,a.attnum,'UPDATE'),'references',pg_catalog.has_column_privilege(r.role,c.oid,a.attnum,'REFERENCES')) order by r.role) from (values('anon'),('authenticated'),('service_role'))r(role))) order by a.attnum) from pg_catalog.pg_attribute a where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped)
 ) order by c.relname) from pg_catalog.pg_class c join pg_catalog.pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname in('profiles','barbershops','barbershop_memberships') and c.relkind='r'),'[]'::jsonb),
 'policies',coalesce((select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('table',tablename,'name',policyname,'roles',roles,'command',cmd,'using',qual,'check',with_check) order by tablename,policyname) from pg_catalog.pg_policies where schemaname='public' and tablename in('profiles','barbershops','barbershop_memberships')),'[]'::jsonb),
 'constraints',coalesce((select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('table',c.relname,'name',k.conname,'type',k.contype,'definition',pg_catalog.pg_get_constraintdef(k.oid)) order by c.relname,k.conname) from pg_catalog.pg_constraint k join pg_catalog.pg_class c on c.oid=k.conrelid join pg_catalog.pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname in('profiles','barbershops','barbershop_memberships')),'[]'::jsonb),
 'indexes',coalesce((select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('table',tablename,'name',indexname,'definition',indexdef) order by tablename,indexname) from pg_catalog.pg_indexes where schemaname='public' and tablename in('profiles','barbershops','barbershop_memberships')),'[]'::jsonb),
 'functions',coalesce((select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('schema',n.nspname,'name',p.proname,'arguments',pg_catalog.pg_get_function_identity_arguments(p.oid),'securityDefiner',p.prosecdef,'settings',p.proconfig,'owner',pg_catalog.pg_get_userbyid(p.proowner),'definition',pg_catalog.pg_get_functiondef(p.oid),'publicExecute',exists(select 1 from pg_catalog.aclexplode(coalesce(p.proacl,pg_catalog.acldefault('f',p.proowner))) a where a.grantee=0 and a.privilege_type='EXECUTE'),'execute',(select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('role',r.role,'allowed',pg_catalog.has_function_privilege(r.role,p.oid,'EXECUTE')) order by r.role) from (values('anon'),('authenticated'),('service_role'))r(role))) order by n.nspname,p.proname) from pg_catalog.pg_proc p join pg_catalog.pg_namespace n on n.oid=p.pronamespace where n.nspname in('public','private') and p.proname in('ensure_own_profile','create_own_barbershop','is_active_member','is_active_admin','list_barbershop_memberships')),'[]'::jsonb),
 'schemaPrivileges',(select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('schema',s.name,'role',r.role,'usage',pg_catalog.has_schema_privilege(r.role,s.name,'USAGE'),'create',pg_catalog.has_schema_privilege(r.role,s.name,'CREATE')) order by s.name,r.role) from (values('public'),('private'))s(name) cross join (values('anon'),('authenticated'),('service_role'))r(role)),
 'businessRowCounts',pg_catalog.jsonb_build_object('profiles',(select count(*) from public.profiles),'barbershops',(select count(*) from public.barbershops),'barbershop_memberships',(select count(*) from public.barbershop_memberships))
) as catalog;
